-- 将该建表 SQL 语句，添加到 yudao-module-ams-biz 模块的 test/resources/sql/create_tables.sql 文件里
CREATE TABLE IF NOT EXISTS "ams_asset"
(
    "id"                bigint   NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "asset_id"          varchar  NOT NULL,
    "name"              varchar  NOT NULL,
    "custom_name"       varchar,
    "trader"            varchar,
    "factory"           varchar,
    "order_date"        varchar,
    "appointment_date"  varchar,
    "pre_shipment_date" varchar,
    "order_id"          varchar,
    "style_no"          varchar,
    "rfid"              varchar,
    "parent_rfid"       varchar,
    "color"             int,
    "unit"              int,
    "size"              varchar,
    "size_standard"     int,
    "number"            int,
    "barcode"           varchar,
    "parent_barcode"    varchar,
    "status"            int      NOT NULL,
    "creator"           varchar           DEFAULT '',
    "create_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater"           varchar           DEFAULT '',
    "update_time"       datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    "deleted"           bit      NOT NULL DEFAULT FALSE,
    "tenant_id"         bigint   NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT '资产清单';